import json, sqlite3, os, sys
obj=json.load(open(os.environ['OUT']))
con=sqlite3.connect('file:'+os.environ['DB']+'?mode=ro', uri=True)
rows=con.execute('SELECT id, slug, name, parent_id FROM career_nodes').fetchall()
by={r[0]:r for r in rows}
for course in obj['courses']:
    for mp in course['career_path_mappings']:
        if mp['career_node_id'] not in by:
            raise SystemExit(f'missing node {mp[\"career_node_id\"]}')
        node=by[mp['career_node_id']]
        if node[1] "'!= mp['"'career_node_slug']:
            raise SystemExit(f'slug mismatch {mp}')
# Rebuild breadcrumb from parent links and compare exact strings.
for course in obj['courses']:
    for mp in course['career_path_mappings']:
        node=by[mp['career_node_id']]; names=[]
        while node:
            names.append(node[2]); node=by.get(node[3])
        breadcrumb=' > '.join(reversed(names))
        if breadcrumb "'!= mp['"'career_breadcrumb']:
            raise SystemExit(f'breadcrumb mismatch {mp[\"career_node_id\"]}: {breadcrumb"'!r} != {mp["career_breadcrumb"]!r}'"')
print('career mappings validated:', sum(len(c['career_path_mappings']) for c in obj['courses']))
PY"

