from html.parser import HTMLParser
from pathlib import Path
import re, sys
class P(HTMLParser):
    def __init__(self):
        super().__init__(); self.main=0; self.skip=0; self.cur=None; self.buf=[]; self.items=[]
    def handle_starttag(self, tag, attrs):
        if tag in ('script','style','noscript','svg'): self.skip += 1
        if tag=='main': self.main += 1
        if self.main and tag in ('h1','h2','h3','h4','h5','h6','p','li','td','th'):
            self.cur=tag; self.buf=[]
    def handle_endtag(self, tag):
        if self.main and self.cur==tag:
            s=re.sub(r'\\s+',' ',' '.join(self.buf)).strip()
            if s: self.items.append((tag,s))
            self.cur=None; self.buf=[]
        if tag=='main' and self.main: self.main -= 1
        if tag in ('script','style','noscript','svg') and self.skip: self.skip -= 1
    def handle_data(self,data):
        if self.main and not self.skip and self.cur: self.buf.append(data)
for f in sorted(Path(sys.argv[1]).glob('*.html')):
    p=P(); p.feed(f.read_text(encoding='utf-8', errors='replace'))
    print('\\n###',f.name)
    seen=set()
    for tag,s in p.items:
        if s in seen: continue
        seen.add(s)
        # omit generic footer and huge boilerplate
        if len(s)>350: s=s[:350]+'...'
        print(f'{tag}: {s}')
PY"

